import {SharedChecklistComponent} from '@github-ui/shared-checklist-component'
import type {StepData} from '@github-ui/shared-checklist-component/Stepper'
import safeStorage from '@github-ui/safe-storage'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {useEffect, useState} from 'react'

import {sendEvent, type SendEventContext} from '@github-ui/hydro-analytics'

export interface CopilotUserChecklistStateProps {
  dismissed: boolean
  checklistState: boolean[]
  timeKey: number
}

export interface CopilotUserChecklistBaseProps {
  stateProps: CopilotUserChecklistStateProps
  checklistSteps: StepData[]
  sessionStorageKey: string
  checklistCategory: string
  dismissedTag: string
  title: string
  testId: string
}

interface SessionState {
  checklist: boolean[]
  storedTime: number
}

type EventName = 'completed' | 'dismiss' | 'step_complete' | 'view'
const trackEvent = (checklistCategory: string, eventName: EventName, properties?: SendEventContext) => {
  sendEvent(`copilot.${checklistCategory}.${eventName}`, properties)
}

export function CopilotUserChecklistBase({
  stateProps: {dismissed, checklistState, timeKey},
  checklistSteps,
  sessionStorageKey,
  checklistCategory,
  dismissedTag,
  title,
  testId,
}: CopilotUserChecklistBaseProps) {
  const trackStepComplete = (stepIndex: number) => {
    trackEvent(checklistCategory, 'step_complete', {step: stepIndex + 1})
  }

  const submitDismiss = async () => {
    const data = new FormData()
    data.set(dismissedTag, 'true')

    await verifiedFetch('/github-copilot/preferences', {
      method: 'PUT',
      body: data,
    })

    trackEvent(checklistCategory, 'dismiss')
  }

  const submitChecklist = async (checklist: boolean[], storedTime: number) => {
    const data = new FormData()
    const safeSessionStorage = safeStorage('sessionStorage')
    data.set(`copilot_${checklistCategory}`, JSON.stringify(checklist))
    await verifiedFetch('/github-copilot/preferences', {
      method: 'PUT',
      body: data,
    })

    safeSessionStorage.setItem(sessionStorageKey, JSON.stringify({checklist, storedTime}))

    const allStepsCompleted = checklist.every(step => step)
    if (allStepsCompleted) {
      trackEvent(checklistCategory, 'completed')
    }
  }

  const safeSessionStorage = safeStorage('sessionStorage')
  const contents = safeSessionStorage.getItem(sessionStorageKey)
  const [loaded, setLoaded] = useState(false)

  let fetchedChecklist
  if (contents === null) {
    fetchedChecklist = checklistState
  } else {
    try {
      const {checklist, storedTime} = JSON.parse(contents) as SessionState
      fetchedChecklist = storedTime === timeKey ? checklist : checklistState
    } catch {
      setLoaded(false)
      throw new Error('free user checklist: failed to parse session storage data')
    }
  }

  useEffect(() => {
    trackEvent(checklistCategory, 'view')
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setLoaded(true)
  }, [checklistCategory])

  return (
    <div data-testid={testId}>
      {loaded && (
        <SharedChecklistComponent
          stepMetadata={checklistSteps}
          dismissed={dismissed}
          onDismiss={submitDismiss}
          checklist={fetchedChecklist}
          onChecklistChange={checklist => submitChecklist(checklist, timeKey)}
          trackStepComplete={trackStepComplete}
          largeHeader
          title={title}
        />
      )}
    </div>
  )
}

try{ CopilotUserChecklistBase.displayName ||= 'CopilotUserChecklistBase' } catch {}